[
  {
    "title": "neutral-stance-instructions-disagree",
    "claim": "Image #6 says every move requires holding a stance and then a technique, but its Lunge Punch row shows a centred stance plus forward technique, and Image #2 explicitly permits leaving the stance centred.",
    "reason": "A new player receives conflicting instructions about whether the stance stick must be moved to attack.",
    "suggest": "Replace the reference instruction with: “Choose a stance or leave that stick centred, then push the technique stick.”"
  },
  {
    "title": "mixed-score-outgrows-hud",
    "claim": "In Image #8, HasanAbi’s stacked half-point fraction extends below the neighbouring name plate and timer, unlike Asmongold’s zero.",
    "reason": "The mixed score becomes a vertically scattered element rather than an immediately readable score beside the fighter’s name.",
    "suggest": "Render mixed scores as a single horizontal unit with a compact ½ glyph, and verify the entire unit stays within the score container at 390×844."
  },
  {
    "title": "controls-lose-direction-labels",
    "claim": "Image #15 shows directional markers on both sticks without the direction-to-action legend visible in Image #3.",
    "reason": "The words “STANCE” and “TECHNIQUE” alone do not tell an unfamiliar player which direction punches, kicks, jumps, or crouches.",
    "suggest": "Keep a compact, readable action legend available beside the sticks, with an explicit player-controlled option to hide it."
  },
  {
    "title": "reference-bottom-is-obscured",
    "claim": "In Image #6, the Back Kick row at the bottom is visibly darkened by a fade while the preceding technique rows remain unobscured.",
    "reason": "A player consulting the move list cannot read that visible row as clearly as the other entries.",
    "suggest": "Remove the fade over readable list content and use a separate scroll cue outside the technique rows."
  },
  {
    "title": "kick-extension-unverified",
    "claim": "Images #13, #19, and #22 label the move “FRONT KICK” while showing a bent attacking knee, but these stills do not establish whether the animation includes a fully extended kick.",
    "reason": "The pictured pose alone cannot settle whether players receive a clear visual indication of the kick’s reach or contact.",
    "suggest": "Capture the complete Front Kick sequence with simulation phase and frame identifiers; change the active pose only if that evidence shows the extension is missing."
  }
]
